const dadosRedis = JSON.parse($json.dadosRegua);

const webhook = $('Webhook').item.json;

const resposta =
  webhook.body?.payload?.vote?.selectedOptions?.[0] ?? null;

const pollId =
  webhook.body?.payload?._data?.RawMessage
    ?.pollUpdateMessage
    ?.pollCreationMessageKey
    ?.ID ?? null;

return [{
  json: {
    itemId: dadosRedis.itemId,
    cliente: dadosRedis.cliente,
    etapa: dadosRedis.etapa,
    resposta,
    pollId
  }
}];
